def git(*args):
    return subprocess.check_output(["git", *args], text=True).strip()
def digest(data): return hashlib.sha256(data).hexdigest()
def main():
    root = pathlib.Path(git("rev-parse", "--show-toplevel")).resolve()
    if pathlib.Path.cwd().resolve() != root: raise RuntimeError("Run from the repository root")
    if git("rev-parse", "HEAD") != BASE: raise RuntimeError("HEAD differs from inspected cf5ac075; re-investigation required")
    branch = git("branch", "--show-current")
    if branch not in ("main", "coderabbit/fix-gameplay-runtime-paths/b2eb964e"):
        raise RuntimeError("Expected main or assigned sandbox branch")
    if "iceyprincess-wise/splendor-assist" not in git("remote", "get-url", "origin").lower():
        raise RuntimeError("Unexpected repository origin")
    entries = json.loads(zlib.decompress(base64.b85decode(PAYLOAD)))
    if len({e["path"] for e in entries}) != len(entries): raise RuntimeError("Duplicate targets")
    originals = {}; staged = {}; written = []
    try:
        for e in entries:
            path = root / e["path"]
            if not path.is_file() or path.is_symlink() or path.resolve() != path.absolute():
                raise RuntimeError("Missing or unsafe target: " + e["path"])
            old = path.read_bytes()
            if digest(old) == e["after"]: raise RuntimeError("Already applied: " + e["path"])
            if digest(old) != e["before"]: raise RuntimeError("Unexpected source: " + e["path"])
            new = e["text"].encode()
            if digest(new) != e["after"]: raise RuntimeError("Corrupt patch payload")
            originals[path] = old
        print("PASS: all source, branch, revision and payload preconditions")
        for e in entries:
            path = root / e["path"]
            fd, tmp = tempfile.mkstemp(prefix=".splendor-patch-", dir=path.parent)
            staged[path] = pathlib.Path(tmp)
            with os.fdopen(fd, "wb") as stream:
                stream.write(e["text"].encode()); stream.flush(); os.fsync(stream.fileno())
            os.chmod(tmp, path.stat().st_mode & 0o777)
        # Recheck all sources after staging; abort if an editor changed a target.
        if any(p.read_bytes() != old for p, old in originals.items()): raise RuntimeError("Source changed during patch")
        for path, tmp in staged.items():
            written.append(path)
            os.replace(tmp, path)
        for e in entries:
            if digest((root / e["path"]).read_bytes()) != e["after"]: raise RuntimeError("Post-write verification failed")
            print("PASS: " + e["path"])
        print("PASS: complete patch applied; no commit or push performed")
    except BaseException:
        for path in written: path.write_bytes(originals[path])
        raise
    finally:
        for tmp in staged.values(): tmp.unlink(missing_ok=True)
if __name__ == "__main__":
    try: main()
    except (Exception, KeyboardInterrupt) as error:
        print("FAIL: " + str(error), file=sys.stderr); sys.exit(1)
